package com.dy.artisan3d.navigationimport androidx.compose.runtime.mutableStateListOfimport androidx.compose.runtime.snapshots.SnapshotStateListimport androidx.compose.runtime.saveable.Saverimport kotlinx.serialization.json.Jsonclass Navigator(startDestination: Any) {    val backStack: SnapshotStateList<Any> = mutableStateListOf(startDestination)    fun navigateTo(destination: Any) {        backStack.add(destination)    }    // Barcha ekranlarni o'chirib, yangi boshlang'ich ekran o'rnatish    fun replaceStack(destination: Any) {        backStack.clear()        backStack.add(destination)    }    fun goBack() {        backStack.removeLastOrNull()    }    companion object {        fun saver(startDestination: Any) = Saver<Navigator, String>(            save = {                // BackStack-ni JSON string qilib saqlaymiz                Json.encodeToString(it.backStack.toList() as List<Screen>)            },            restore = { savedString ->                // JSON-dan yana List-ga qaytaramiz                val list = Json.decodeFromString<List<Screen>>(savedString)                val nav = Navigator(startDestination)                nav.backStack.clear()                nav.backStack.addAll(list)                nav            }        )    }}